     */
    public function setBindValue(string $bindKey, string $value): void
    {
        switch ($bindKey) {
            case 'counter': if ($this->counter !== (int)$value) { $this->counter = (int)$value; } break;
            case 'trackedProp': if ($this->trackedProp !== (int)$value) { $this->trackedProp = (int)$value; } break;
            case 'otherCount': if ($this->otherCount !== (int)$value) { $this->otherCount = (int)$value; } break;
