            case 'totalRenders': if ($this->totalRenders !== (int)$value) { $this->totalRenders = (int)$value; } break;
            case 'scrollPos': if ($this->scrollPos !== (int)$value) { $this->scrollPos = (int)$value; } break;
            case 'version': if ($this->version !== $value) { $this->version = $value; } break;
            case 'msgCount': if ($this->msgCount !== (int)$value) { $this->msgCount = (int)$value; } break;
            case 'hoverCycle': if ($this->hoverCycle !== (int)$value) { $this->hoverCycle = (int)$value; } break;
            case 'hoveredIdx': if ($this->hoveredIdx !== (int)$value) { $this->hoveredIdx = (int)$value; } break;
            case 'textCycle': if ($this->textCycle !== (int)$value) { $this->textCycle = (int)$value; } break;
            case 'dynaCount': if ($this->dynaCount !== (int)$value) { $this->dynaCount = (int)$value; } break;
