    public function getBindValue(string $bindKey): string
    {
        switch ($bindKey) {
            case 'counter': return $this->counter;
            case 'trackedProp': return $this->trackedProp;
            case 'otherCount': return $this->otherCount;
            case 'cycleCount': return $this->cycleCount;
            case 'totalRenders': return $this->totalRenders;
            case 'scrollPos': return $this->scrollPos;
            case 'version': return $this->version;
            case 'msgCount': return $this->msgCount;
            case 'hoverCycle': return $this->hoverCycle;
            case 'hoveredIdx': return $this->hoveredIdx;
            case 'textCycle': return $this->textCycle;
            case 'dynaCount': return $this->dynaCount;
            case 'stCycle': return $this->stCycle;
            case 'stCount': return $this->stCount;
            case 'ideLogCount': return $this->ideLogCount;
            case 'cursorLine': return $this->cursorLine;
            case 'cursorCol': return $this->cursorCol;
            case 'gitBranch': return $this->gitBranch;
            case 'lintWarnings': return $this->lintWarnings;
            case 'currentCase': return $this->currentCase;
            default: return '';
        }
    }

